import { aiAnswerSchema } from "./race-wizard";

// IDs and hashes are copied from the exported pack, never generated by ChatGPT.
export const bridgeSchema = {
  type: "object",
  additionalProperties: false,
  required: [
    "bridge_version",
    "race_id",
    "snapshot_id",
    "input_hash",
    "model_version_id",
    "information_cutoff_at",
    "kind",
    "version",
    "answer",
  ],
  properties: {
    bridge_version: { const: "1" },
    race_id: { type: "string", minLength: 1 },
    snapshot_id: { type: "string", minLength: 1 },
    input_hash: { type: "string", minLength: 1 },
    model_version_id: { type: "string", minLength: 1 },
    information_cutoff_at: { type: "string", format: "date-time" },
    kind: { enum: ["morning", "final", "reanalysis"] },
    version: { type: "integer", minimum: 1 },
    supersedes_prediction_id: { type: "string", minLength: 1 },
    final_changes: { type: "array", items: { type: "object" } },
    answer: aiAnswerSchema,
  },
};

export const raceKey = (id: string) => id.replace(/[^A-Za-z0-9_-]/g, "_");
